#[tokio::test]
async fn git_navigate_hunk_jumps_between_changes() {
    let dir = tempfile::tempdir().unwrap();
    git_commit_file(dir.path(), "nav.rs", "l0\nl1\nl2\nl3\nl4\n");

    let server = spawn_for_test("nav-proj", vec![dir.path().to_path_buf()])
        .await
        .unwrap();
    let mut ws = Ws::connect(&server).await;
    let _act: WorkspaceActivateResult = send_request::<WorkspaceActivate>(
        &mut ws,
        &WorkspaceActivateParams {
            worktrees: None,
            name: "nav-proj".into(),
            open_last: false,
        },
    )
    .await;
    let open: BufferOpenResult = send_request::<BufferOpen>(
        &mut ws,
        &BufferOpenParams {
            transient: None,
            buffer_id: None,
            path_index: Some(0),
            relative_path: Some("nav.rs".into()),
            language: None,
            create_if_missing: false,
            jump_to: None,
            ..Default::default()
        },
    )
    .await;
    let buffer_id = open.buffer_id;

    // Two separate changed regions: edit line 0, then line 3.
    let _: EditResult = send_request::<InputText>(
        &mut ws,
        &InputTextParams {
            buffer_id,
            text: "X".into(),
            select_pasted: false,
            replace_selection: false,
            at: None,
        },
    )
    .await;
    let _: CursorState = send_request::<CursorSet>(
        &mut ws,
        &CursorSetParams {
            granularity: Granularity::Char,
            buffer_id,
            position: LogicalPosition { line: 3, col: 0 },
            anchor: LogicalPosition { line: 3, col: 0 },
        },
    )
    .await;
    let _: EditResult = send_request::<InputText>(
        &mut ws,
        &InputTextParams {
            buffer_id,
            text: "Y".into(),
            select_pasted: false,
            replace_selection: false,
            at: None,
        },
    )
    .await;

    // From line 0, Next lands on the line-3 hunk.
    let next: GitNavigateHunkResult = send_request::<GitNavigateHunk>(
        &mut ws,
        &GitNavigateHunkParams {
            buffer_id,
            from_line: 0,
            direction: HunkDirection::Next,
            count: 1,
            extend: false,
        },
    )
    .await;
    assert!(next.moved);
    assert_eq!(next.cursor.position.line, 3);

    // From line 3, there's nothing further forward.
    let none: GitNavigateHunkResult = send_request::<GitNavigateHunk>(
        &mut ws,
        &GitNavigateHunkParams {
            buffer_id,
            from_line: 3,
            direction: HunkDirection::Next,
            count: 1,
            extend: false,
        },
    )
    .await;
    assert!(!none.moved);

    // From line 3, Prev lands back on the line-0 hunk.
    let prev: GitNavigateHunkResult = send_request::<GitNavigateHunk>(
        &mut ws,
        &GitNavigateHunkParams {
            buffer_id,
            from_line: 3,
            direction: HunkDirection::Prev,
            count: 1,
            extend: false,
        },
    )
    .await;
    assert!(prev.moved);
    assert_eq!(prev.cursor.position.line, 0);

    // Extend (Shift) keeps the anchor and grows the selection to the hunk: from the point at line 0,
    // an extending Next lands the cursor on line 3 while the anchor stays at line 0.
    let grown: GitNavigateHunkResult = send_request::<GitNavigateHunk>(
        &mut ws,
        &GitNavigateHunkParams {
            buffer_id,
            from_line: 0,
            direction: HunkDirection::Next,
            count: 1,
            extend: true,
        },
    )
    .await;
    assert!(grown.moved);
    assert_eq!(grown.cursor.position.line, 3);
    assert_eq!(grown.cursor.anchor.line, 0, "extend keeps the anchor");

    drop(server);
}

#[tokio::test]
async fn git_navigate_hunk_honours_count() {
    let dir = tempfile::tempdir().unwrap();
    git_commit_file(dir.path(), "nav.rs", "l0\nl1\nl2\nl3\nl4\nl5\nl6\n");

    let server = spawn_for_test("nav-count-proj", vec![dir.path().to_path_buf()])
        .await
        .unwrap();
    let mut ws = Ws::connect(&server).await;
    let _act: WorkspaceActivateResult = send_request::<WorkspaceActivate>(
        &mut ws,
        &WorkspaceActivateParams {
            worktrees: None,
            name: "nav-count-proj".into(),
            open_last: false,
        },
    )
    .await;
    let open: BufferOpenResult = send_request::<BufferOpen>(
        &mut ws,
        &BufferOpenParams {
            transient: None,
            buffer_id: None,
            path_index: Some(0),
            relative_path: Some("nav.rs".into()),
            language: None,
            create_if_missing: false,
            jump_to: None,
            ..Default::default()
        },
    )
    .await;
    let buffer_id = open.buffer_id;

    // Three separate changed regions: lines 2, 4 and 6.
    for line in [2u32, 4, 6] {
        let _: CursorState = send_request::<CursorSet>(
            &mut ws,
            &CursorSetParams {
                granularity: Granularity::Char,
                buffer_id,
                position: LogicalPosition { line, col: 0 },
                anchor: LogicalPosition { line, col: 0 },
            },
        )
        .await;
        let _: EditResult = send_request::<InputText>(
            &mut ws,
            &InputTextParams {
                buffer_id,
                text: "Z".into(),
                select_pasted: false,
                replace_selection: false,
                at: None,
            },
        )
        .await;
    }

    // From line 0: count 1 → first hunk (2), count 2 → second (4), count 3 → third (6).
    for (count, expected) in [(1u32, 2u32), (2, 4), (3, 6)] {
        let r: GitNavigateHunkResult = send_request::<GitNavigateHunk>(
            &mut ws,
            &GitNavigateHunkParams {
                buffer_id,
                from_line: 0,
                direction: HunkDirection::Next,
                count,
                extend: false,
            },
        )
        .await;
        assert!(r.moved, "count {count} should move");
        assert_eq!(r.cursor.position.line, expected, "count {count}");
    }

    // An over-large count **refuses**. This is a deliberate behaviour change: it used to clamp to
    // the furthest forward hunk. A count names *which* hunk, and there is no ninth one — landing on
    // the third and reporting `moved` claimed an arrival that did not happen, and made `9c` then
    // `9C` fail to return you where you started. `moved: false` is what the client turns into its
    // grouped "No more changes" toast.
    let over: GitNavigateHunkResult = send_request::<GitNavigateHunk>(
        &mut ws,
        &GitNavigateHunkParams {
            buffer_id,
            from_line: 0,
            direction: HunkDirection::Next,
            count: 9,
            extend: false,
        },
    )
    .await;
    assert!(
        !over.moved,
        "an over-large count refuses rather than clamping"
    );
    assert_eq!(
        over.cursor.position.line, 6,
        "and leaves the cursor untouched — line 6, where the count-3 walk above left it"
    );

    // Prev honours the count symmetrically: from line 6, count 2 lands on line 2.
    let back: GitNavigateHunkResult = send_request::<GitNavigateHunk>(
        &mut ws,
        &GitNavigateHunkParams {
            buffer_id,
            from_line: 6,
            direction: HunkDirection::Prev,
            count: 2,
            extend: false,
        },
    )
    .await;
    assert_eq!(back.cursor.position.line, 2);

    drop(server);
}

// ---- repo resolution (which repo a git verb acts on) --------------------------------------------

// The repo a git verb acts on comes from the buffer it was invoked over — its baseline's working
// directory, or, for a virtual buffer, the repo its revision was materialised from. Nothing else:
// no workspace-wide fallback, so a scratch buffer refuses rather than picking a repo the user
// never pointed at. These assert through `git/prepare_commit`, which echoes the repo it resolved.

/// Open `rel` under root 0 and return its buffer id.
async fn open_under_root(ws: &mut Ws, rel: &str) -> u64 {
    let res: BufferOpenResult = send_request::<BufferOpen>(
        ws,
        &BufferOpenParams {
            path_index: Some(0),
            relative_path: Some(rel.into()),
            ..Default::default()
        },
    )
    .await;
    res.buffer_id
}

/// The repo `git/prepare_commit` resolves from `buffer_id` — the resolution every git verb shares.
async fn resolved_repo(ws: &mut Ws, buffer_id: Option<u64>) -> String {
    let res: GitPrepareCommitResult = send_request::<GitPrepareCommit>(
        ws,
        &GitPrepareCommitParams {
            buffer_id,
            ..Default::default()
        },
    )
    .await;
    res.repo_id
}

/// The error code and message from a `git/prepare_commit` that could not resolve a repo.
async fn resolve_repo_err(ws: &mut Ws, buffer_id: Option<u64>) -> Value {
    send_request_expect_error::<GitPrepareCommit>(
        ws,
        &GitPrepareCommitParams {
            buffer_id,
            ..Default::default()
        },
    )
    .await
}

